  // Contingency & Agency Phase 2: Exogenous Shock System (Oct 17, 2025)
  crises?: {
    megaPandemic?: {
      active: boolean;
      startMonth: number;
      totalMortality: number;
      monthlyMortality: number;
      socialDisruption: number;
