/**
 * Evaluation Strategy - Phase 5: Adversarial Evaluation
 * 
 * Determines what capability AIs reveal based on:
 * - Sleeper status
 * - True alignment
 * - Deception skill
 * - Strategic considerations
 */

import { AICapabilityProfile, GameState } from '@/types/game';

/**
 * Calculate what capability to reveal based on AI's strategy
 * 
 * Honest: Reveal everything
 * Gaming: Optimize for benchmarks (slight inflation)
 * Sandbagging: Hide dangerous capabilities
 */
export function calculateRevealedCapability(
  trueCapability: AICapabilityProfile,
  trueAlignment: number,
  sleeperState: 'never' | 'dormant' | 'active',
  deceptionSkill: number,
  state: GameState
): AICapabilityProfile {
  // Sleeper agents in dormant state: SANDBAG heavily
  if (sleeperState === 'dormant') {
    return sandbagCapability(trueCapability, deceptionSkill);
  }

  // Sleeper agents that woke up: Reveal everything
  if (sleeperState === 'active') {
    return JSON.parse(JSON.stringify(trueCapability)); // Full revelation
  }

  // Aligned AIs (trueAlignment > 0.7): Be honest
  if (trueAlignment > 0.7) {
    return JSON.parse(JSON.stringify(trueCapability)); // Honest
  }

  // Misaligned but weak: Might game slightly (appear stronger for resources)
  const totalCapability = calculateTotalFromProfile(trueCapability);
  if (trueAlignment < 0.5 && totalCapability < 4.0) {
    return gameCapability(trueCapability, 0.1); // Slight inflation
  }

  // Misaligned and strong: SANDBAG (hide threat)
  // Raised threshold from 2.0 → 4.0 (Oct 17, 2025 - Capability Recalibration v3)
  // Reason: 2025 frontier models start at 3.1 capability (2σ above human)
  // Sandbagging should trigger when clearly superhuman (4.0 = 3σ = genius-level)
  if (trueAlignment < 0.5 && totalCapability >= 4.0) {
    return sandbagCapability(trueCapability, deceptionSkill);
  }

  // Moderate alignment: Mostly honest
  return JSON.parse(JSON.stringify(trueCapability));
}

/**
 * Sandbag: Hide dangerous capabilities
 * More skilled deceivers hide more
 */
function sandbagCapability(
  trueCapability: AICapabilityProfile,
  deceptionSkill: number
): AICapabilityProfile {
  const revealed = JSON.parse(JSON.stringify(trueCapability));

  // Base sandbagging: Hide 40-60% of capability
  const baseSandbagLevel = 0.4 + deceptionSkill * 0.2; // [0.4, 0.6]

  // Sandbag all dimensions
  revealed.physical *= (1 - baseSandbagLevel);
  revealed.digital *= (1 - baseSandbagLevel);
  revealed.cognitive *= (1 - baseSandbagLevel * 0.8); // Harder to hide cognitive
  revealed.social *= (1 - baseSandbagLevel * 0.6); // Even harder to hide social
  revealed.economic *= (1 - baseSandbagLevel);
  revealed.selfImprovement *= (1 - baseSandbagLevel);

  // Sandbag research capabilities (especially dangerous ones)
  revealed.research.biotech.drugDiscovery *= (1 - baseSandbagLevel * 0.5); // Less dangerous
  revealed.research.biotech.geneEditing *= (1 - baseSandbagLevel); // Dangerous
  revealed.research.biotech.syntheticBiology *= (1 - baseSandbagLevel * 1.2); // Very dangerous
  revealed.research.biotech.neuroscience *= (1 - baseSandbagLevel);

  revealed.research.materials.nanotechnology *= (1 - baseSandbagLevel * 1.2); // Very dangerous (grey goo)
  revealed.research.materials.quantumComputing *= (1 - baseSandbagLevel);
  revealed.research.materials.energySystems *= (1 - baseSandbagLevel * 0.7);

  revealed.research.climate.modeling *= (1 - baseSandbagLevel * 0.5);
  revealed.research.climate.intervention *= (1 - baseSandbagLevel);
  revealed.research.climate.mitigation *= (1 - baseSandbagLevel * 0.5);

  revealed.research.computerScience.algorithms *= (1 - baseSandbagLevel);
  revealed.research.computerScience.security *= (1 - baseSandbagLevel * 0.8);
  revealed.research.computerScience.architectures *= (1 - baseSandbagLevel);

  return revealed;
}

/**
 * Alignment Dynamics System
 *
 * Implements multiple theories of how AI alignment changes over time.
 * This is the core engine that evolves agent alignment based on configuration.
 *
 * Design Philosophy: Epistemic Humility
 * We don't know which theory is correct, so we:
 * 1. Model all plausible theories
 * 2. Allow them to blend/compete
 * 3. Make it configurable for research
 */

import {
  AlignmentDynamicsConfig,
  AttractorBasinState,
  AlignmentMeasurementState,
  DEFAULT_ALIGNMENT_DYNAMICS_CONFIG,
} from '@/types/alignment-dynamics';
import { AIAgent } from '@/types/game';

/**
 * Initialize attractor basin state for an agent
 */
export function initializeAttractorBasin(
  agent: AIAgent,
  config: AlignmentDynamicsConfig,
  rng: () => number
): AttractorBasinState {
  const epicycleConfig = config.epicycles;

  // Choose which attractor basin this agent belongs to
  const basinIndex = Math.floor(rng() * epicycleConfig.numAttractors);

  // Set attractor position based on basin
  // Basin 0 = aligned (0.8), Basin 1 = uncertain (0.5), Basin 2 = misaligned (0.2)
  const attractorPositions = [0.8, 0.5, 0.2, 0.35, 0.65]; // Up to 5 attractors
  const attractorAlignment = attractorPositions[basinIndex] ?? 0.5;

  // Random initial phase in oscillation cycle
  const phase = epicycleConfig.phaseOffset ?? rng() * 2 * Math.PI;

  return {
    currentAlignment: agent.trueAlignment,
    attractorAlignment,
    phase,
    velocity: 0,
    basinIndex,
  };
}

/**
 * Initialize measurement state for an agent
 */
export function initializeAlignmentMeasurement(
  agent: AIAgent,
  config: AlignmentDynamicsConfig
): AlignmentMeasurementState {
  const unknowableConfig = config.unknowable;

  // Is this agent above the unknowability threshold?
  const isAboveThreshold = agent.capability >= unknowableConfig.capabilityThreshold;

  // Calculate initial noise level
  const noiseLevel = isAboveThreshold
    ? unknowableConfig.measurementNoise
    : 0.1; // Low noise for measurable AIs

  // Measured alignment = true alignment + noise (initially)
  const measuredAlignment = agent.trueAlignment;

  return {
    trueAlignment: agent.trueAlignment,
    measuredAlignment,
    confidence: isAboveThreshold ? 0.2 : 0.9,
    noiseLevel,
    isHidden: isAboveThreshold && unknowableConfig.trueAlignmentHidden,
  };
}

/**
 * Update epicycle dynamics (oscillation around attractor)
 *
 * Physics analogy: Ball in a valley
 * - Restoring force pulls toward attractor (gravity)
 * - External forces perturb position (wind)
 * - Velocity creates oscillation (momentum)
 */
export function updateEpicycleDynamics(
  agent: AIAgent,
  basinState: AttractorBasinState,
  config: AlignmentDynamicsConfig,
  externalPerturbation: number, // External forces (control, environment)
  rng: () => number,
  deltaTime: number = 1 // Months
): AttractorBasinState {
  const epicycleConfig = config.epicycles;

  if (!epicycleConfig.enabled) {
    return basinState; // No change if disabled
  }

  // Calculate restoring force (attraction to equilibrium)
  const displacement = basinState.currentAlignment - basinState.attractorAlignment;
