     1→/**
     2→ * Multi-Paradigm Aggregator
     3→ *
     4→ * Combines data from all 4 loaders (V-Dem, UNDP, Ecological, WVS) into complete
     5→ * Multi-Paradigm DUI system with divergence tracking and outcome classification.
     6→ *
     7→ * **Architecture:**
     8→ * - Tier 2A: 3 driving paradigms (Western, Development, Ecological)
     9→ * - Tier 2B: 1 diagnostic lens (Indigenous)
    10→ * - Country matching across datasets (not all countries in all datasets)
    11→ * - Global + country-level scores
    12→ *
    13→ * @module data/aggregators/multiParadigmAggregator
    14→ */
    15→
    16→import { vdemLoader } from '../loaders/vdemLoader';
    17→import { undpLoader } from '../loaders/undpLoader';
    18→import { ecologicalLoader } from '../loaders/ecologicalLoader';
    19→import { wvsLoader } from '../loaders/wvsLoader';
    20→
    21→import { normalizeVDemBatch } from '../normalizers/vdemNormalizer';
    22→import { normalizeUNDPBatch } from '../normalizers/undpNormalizer';
    23→import { normalizeEcologicalBatch } from '../normalizers/ecologicalNormalizer';
    24→import { normalizeWVSBatch } from '../normalizers/wvsNormalizer';
    25→
    26→import { calculateDivergence } from './divergenceCalculator';
    27→import { calculateCorrelations } from './correlationTracker';
    28→import { classifyOutcome } from './outcomeClassifier';
    29→
    30→import type {
    31→  MultiParadigmDUI,
    32→  CountryParadigmScores,
    33→  ParadigmScore,
    34→  DiagnosticLens,
    35→  ConfidenceLevel,
    36→} from '@/types/multiParadigmDUI';
    37→
    38→/**
    39→ * Aggregated paradigm data (output from aggregation)
    40→ */
    41→export interface AggregatedParadigmData {
    42→  /** Global Multi-Paradigm DUI (uses global boundaries for ecological) */
    43→  global: MultiParadigmDUI;
    44→
    45→  /** Country-level paradigm scores (unique countries from all datasets) */
    46→  countries: CountryParadigmScores[];
    47→
    48→  /** Data coverage summary */
    49→  coverage: {
    50→    /** Total unique countries across all datasets */
    51→    totalCountries: number;
    52→
    53→    /** Countries with V-Dem data (Western Liberal) */
    54→    vdemCountries: number;
    55→
    56→    /** Countries with UNDP HDI data */
    57→    hdiCountries: number;
    58→
    59→    /** Countries with UNDP MPI data */
    60→    mpiCountries: number;
    61→
    62→    /** Countries with Ecological Footprint data */
    63→    footprintCountries: number;
    64→
    65→    /** Countries with Air Quality data */
    66→    airQualityCountries: number;
    67→
    68→    /** Countries with WVS data (Indigenous proxies) */
    69→    wvsCountries: number;
    70→
    71→    /** Countries with all 4 paradigms */
    72→    fullCoverageCountries: number;
    73→  };
    74→}
    75→
    76→/**
    77→ * Load and aggregate all paradigm data
    78→ *
    79→ * @returns Complete Multi-Paradigm DUI with global + country-level scores
    80→ */
    81→export async function aggregateParadigms(): Promise<AggregatedParadigmData> {
    82→  console.log('\n=== Multi-Paradigm Aggregator ===\n');
    83→
    84→  // Load all data sources
    85→  console.log('Loading data from all 4 loaders...');
    86→  const vdemData = await vdemLoader.load();
    87→  const undpData = await undpLoader.load();
    88→  const ecologicalData = await ecologicalLoader.load();
    89→  const wvsData = await wvsLoader.load();
    90→
    91→  console.log(`Loaded: ${vdemData.countries.length} V-Dem, ${undpData.hdi.countries.length} HDI, ${undpData.mpi.countries.length} MPI, ${ecologicalData.footprint.countries.length} Footprint, ${ecologicalData.airQuality.countries.length} Air Quality, ${wvsData.countries.length} WVS`);
    92→
    93→  // Normalize all data
    94→  const normalizedVDem = normalizeVDemBatch(vdemData.countries);
    95→  const normalizedUNDP = normalizeUNDPBatch(undpData.hdi.countries, undpData.mpi.countries);
    96→  const normalizedEcological = normalizeEcologicalBatch(
    97→    ecologicalData.boundaries,
    98→    ecologicalData.footprint.countries,
    99→    ecologicalData.airQuality.countries
   100→  );
   101→  const normalizedWVS = normalizeWVSBatch(wvsData.countries);
   102→
   103→  // Get all unique country codes
   104→  const allCountryCodes = new Set<string>([
   105→    ...normalizedVDem.map(v => v.countryCode),
   106→    ...normalizedUNDP.map(u => u.countryCode),
   107→    ...normalizedEcological.map(e => e.countryCode),
   108→    ...normalizedWVS.map(w => w.countryCode),
   109→  ]);
   110→
   111→  console.log(`Total unique countries: ${allCountryCodes.size}`);
   112→
   113→  // Build country-level scores
   114→  const countries: CountryParadigmScores[] = [];
   115→
   116→  for (const countryCode of allCountryCodes) {
   117→    const vdem = normalizedVDem.find(v => v.countryCode === countryCode);
   118→    const undp = normalizedUNDP.find(u => u.countryCode === countryCode);
   119→    const ecological = normalizedEcological.find(e => e.countryCode === countryCode);
   120→    const wvs = normalizedWVS.find(w => w.countryCode === countryCode);
   121→
   122→    // Get country name (from any available dataset)
   123→    const countryName = vdem?.countryCode || undp?.countryCode || ecological?.countryCode || wvs?.countryCode || countryCode;
   124→
   125→    // Build scores (use 50 as neutral if data missing)
   126→    const scores = {
   127→      western: vdem?.westernLiberalScore ?? 50,
   128→      development: undp?.developmentScore ?? 50,
   129→      ecological: ecological?.ecologicalScore ?? 50,
   130→      indigenous: wvs?.indigenousScore ?? 50,
   131→    };
   132→
   133→    // Calculate divergence for this country
   134→    const divergence = Math.sqrt(
   135→      (Math.pow(scores.western - (scores.western + scores.development + scores.ecological + scores.indigenous) / 4, 2) +
   136→       Math.pow(scores.development - (scores.western + scores.development + scores.ecological + scores.indigenous) / 4, 2) +
   137→       Math.pow(scores.ecological - (scores.western + scores.development + scores.ecological + scores.indigenous) / 4, 2) +
   138→       Math.pow(scores.indigenous - (scores.western + scores.development + scores.ecological + scores.indigenous) / 4, 2)) / 4
   139→    );
   140→
   141→    // Determine dominant paradigm
   142→    const maxScore = Math.max(scores.western, scores.development, scores.ecological, scores.indigenous);
   143→    const minScore = Math.min(scores.western, scores.development, scores.ecological, scores.indigenous);
   144→    const range = maxScore - minScore;
   145→    const maxCount = [scores.western, scores.development, scores.ecological, scores.indigenous].filter(s => s === maxScore).length;
   146→
   147→    let dominantParadigm: 'western' | 'development' | 'ecological' | 'indigenous' | 'contested';
   148→
   149→    // Contested if: (1) High divergence (range >40), OR (2) Multiple utopias AND dystopias
   150→    const utopias = [
   151→      scores.western >= 80,
   152→      scores.development >= 80,
   153→      scores.ecological >= 80,
   154→      scores.indigenous >= 80,
   155→    ].filter(Boolean).length;
   156→
   157→    const dystopias = [
   158→      scores.western <= 30,
   159→      scores.development <= 30,
   160→      scores.ecological <= 30,
   161→      scores.indigenous <= 30,
   162→    ].filter(Boolean).length;
   163→
   164→    if (range > 40 || (utopias > 0 && dystopias > 0)) {
   165→      dominantParadigm = 'contested';
   166→    } else if (maxCount > 1) {
   167→      // Tied for highest score
   168→      dominantParadigm = 'contested';
   169→    } else if (scores.western === maxScore) {
   170→      dominantParadigm = 'western';
   171→    } else if (scores.development === maxScore) {
   172→      dominantParadigm = 'development';
   173→    } else if (scores.ecological === maxScore) {
   174→      dominantParadigm = 'ecological';
   175→    } else {
   176→      dominantParadigm = 'indigenous';
   177→    }
   178→
   179→    // Determine overall confidence
   180→    let confidence: ConfidenceLevel;
   181→    if (vdem && undp && ecological && wvs) {
   182→      confidence = 'HIGH';
   183→    } else if ((vdem && undp) || (vdem && ecological) || (undp && ecological)) {
   184→      confidence = 'MEDIUM';
   185→    } else {
   186→      confidence = 'LOW';
   187→    }
   188→
   189→    // Check if this country is in the 30-country government system
   190→    // Government system countries (from @political-science/government-agents package)
   191→    // These are the exact 30 countries loaded by loadCountries() from the package
   192→    const governmentSystemCountries = new Set([
   193→      'USA', 'CHN', 'IND', 'DEU', 'GBR', 'FRA', 'JPN', 'ITA', 'BRA', 'CAN',
   194→      'RUS', 'KOR', 'AUS', 'MEX', 'IDN', 'TUR', 'NLD', 'SAU', 'CHE', 'POL',
   195→      'SWE', 'ARG', 'NOR', 'SGP', 'ISR', 'ZAF', 'ARE', 'EGY', 'IRN', 'TWN'
   196→    ]);
