      month: state.currentMonth
    });
    const volunteerPrograms = assertStateProperty(purposeInfra, 'volunteerPrograms', {
      location: 'SocialCohesionUpdatePhase.calculatePurposeInfrastructure',
      month: state.currentMonth
    });
    const purposePrograms = (educationAccess + creativeSpaces + volunteerPrograms) / 3;
