    adequacy: number;                 // [0, 1] Covers basic needs? (rent + food + healthcare)
    fundingSource: 'robot_tax' | 'wealth_tax' | 'vat' | 'mixed';
    monthlyCost: number;              // $B per month (15% of GDP = ~$400B/month US-scale)
  };

