    64→  const safetyResearch = state.government.evaluationInvestment?.alignmentTests ?? 1.0;
    65→  let safetyGap = Math.max(0, capabilityGrowthRate - (safetyResearch * 0.01));
    66→  
    67→  // Organizations worsen safety debt if prioritizing profit over safety
    68→  const unsafeOrgs = state.organizations.filter(o =>
    69→    o.type === 'private' &&
