   125→   * Invalidate cache (call after population phases run)
   126→   */
   127→  invalidateCache(): void {
   128→    this.cache = null;
   129→  }
   130→
   131→  /**
   132→   * Build cache from game state
   133→   * O(n) but only called once per query batch
   134→   */
   135→  private buildCache(): void {
   136→    const cache = new Map<string, PopulationData>();
   137→
   138→    // Add regional populations
   139→    if (this.state.humanPopulationSystem.regionalPopulations) {
   140→      for (const region of this.state.humanPopulationSystem.regionalPopulations) {
   141→        const decline = 1 - (region.population / region.baselinePopulation);
   142→
   143→        cache.set(region.name, {
   144→          current: region.population,
   145→          baseline: region.baselinePopulation,
   146→          decline,
   147→          locationType: 'region',
   148→          location: region.name
   149→        });
   150→      }
   151→    }
   152→
   153→    // Add country populations
   154→    if (this.state.countryPopulationSystem) {
   155→      const countries = Object.values(this.state.countryPopulationSystem.countries);
   156→      for (const country of countries) {
   157→        const decline = 1 - (country.population / country.baselinePopulation);
   158→
   159→        cache.set(country.name, {
   160→          current: country.population,
   161→          baseline: country.baselinePopulation,
   162→          decline,
   163→          locationType: 'country',
   164→          location: country.name,
   165→          parentRegion: country.region as RegionName
   166→        });
   167→      }
   168→    }
   169→
   170→    // Add global (weighted average of all regions)
   171→    const globalData = this.calculateGlobalData();
   172→    cache.set('Global', globalData);
   173→
