    97→  }
    98→
    99→  // Oceania → doesn't have a regional population, map to closest (could be its own region)
   100→  if (normalized.includes('oceania') || normalized.includes('pacific')) {
   101→    return 'East Asia'; // Closest approximation
   102→  }
   103→
   104→  // Default to North America (most common case)
   105→  console.warn(`⚠️  Unknown country region "${countryRegion}", defaulting to North America`);
   106→  return 'North America';
   107→}
   108→
   109→/**
   110→ * Get all countries belonging to a region
