   138→export function createRegionCountryMaps(countries: Record<CountryName, { region: string }>) {
   139→  const regionToCountries = new Map<RegionName, Set<CountryName>>();
   140→  const countryToRegion = new Map<CountryName, RegionName>();
   141→
