   148→    'Sub-Saharan Africa',
   149→    'Latin America',
   150→    'Middle East & North Africa'
   151→  ];
   152→
   153→  for (const region of regions) {
   154→    regionToCountries.set(region, new Set());
   155→  }
   156→
   157→  // Populate mappings
