export function mapCountryRegionToStandardRegion(countryRegion: string): RegionName {
  const normalized = countryRegion.toLowerCase().trim();

  // Europe (combines Western Europe + Eastern Europe)
  if (normalized.includes('europe')) {
    return 'Europe';
  }

  // Eastern Asia (UN statistical name)
  if (normalized.includes('east asia') || normalized === 'east asia') {
    return 'Eastern Asia';
  }

  // Southern Asia (UN statistical name)
  if (normalized.includes('south asia') || normalized === 'south asia') {
    return 'Southern Asia';
  }

  // South-East Asia (UN statistical name, with hyphen)
  if (normalized.includes('southeast asia') || normalized.includes('south-east asia') || normalized === 'southeast asia') {
