              </div>
              <div className="flex justify-between p-2 rounded" style={{ backgroundColor: 'var(--color-near-black)' }}>
                <span style={{ color: 'var(--white-60)' }}>Public Awareness:</span>
                <span className="font-mono" style={{ color: 'var(--white-80)' }}>
