            <p className="text-xs" style={{ color: 'var(--white-40)' }}>Hide true capabilities</p>
          </div>
        </div>
      </Panel>

      {/* Sleeper Agents Alert */}
      {(stats.sleepers.dormant > 0 || stats.sleepers.active > 0) && (
