   341→  /**
   342→   * Detect when metrics cross critical thresholds
   343→   */
   344→  private detectThresholdCrossings(prevState: GameState, currentState: GameState): void {
   345→    const month = currentState.currentMonth;
   346→    
   347→    // AI Capability
   348→    const prevCap = prevState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   349→    const currCap = currentState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   350→    this.checkThresholds('aiCapability', prevCap, currCap, this.CAPABILITY_THRESHOLDS, month);
   351→    
   352→    // AI Alignment
   353→    const prevAlign = prevState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / prevState.aiAgents.length;
   354→    const currAlign = currentState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / currentState.aiAgents.length;
   355→    this.checkThresholds('alignment', prevAlign, currAlign, this.ALIGNMENT_THRESHOLDS, month);
   356→    
   357→    // Unemployment
   358→    this.checkThresholds('unemployment', prevState.society.unemploymentLevel, 
   359→      currentState.society.unemploymentLevel, this.UNEMPLOYMENT_THRESHOLDS, month);
   360→    
   361→    // Trust
   362→    this.checkThresholds('trustInAI', prevState.society.trustInAI, 
   363→      currentState.society.trustInAI, this.TRUST_THRESHOLDS, month);
   364→  }
   365→  
   366→  /**
   367→   * Check if a metric crossed any thresholds
   368→   */
   369→  private checkThresholds(
   370→    metric: string,
   371→    prevValue: number,
   372→    currValue: number,
   373→    thresholds: number[],
   374→    month: number
   375→  ): void {
   376→    for (const threshold of thresholds) {
   377→      // Crossing upward
   378→      if (prevValue < threshold && currValue >= threshold) {
   379→        this.thresholdCrossings.push({
   380→          month,
   381→          metric,
   382→          threshold,
   383→          value: currValue,
   384→          direction: 'up'
   385→        });
   386→      }
   387→      // Crossing downward
   388→      if (prevValue > threshold && currValue <= threshold) {
   389→        this.thresholdCrossings.push({
   390→          month,
   391→          metric,
   392→          threshold,
   393→          value: currValue,
   394→          direction: 'down'
   395→        });
   396→      }
   397→    }
   398→  }
   399→  
   400→  /**
   401→   * Calculate growth rates for key metrics
   402→   */
   403→  private calculateGrowthRates(prevState: GameState, currentState: GameState): void {
   404→    const month = currentState.currentMonth;
   405→    
   406→    // AI Capability growth
   407→    const prevCap = prevState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   408→    const currCap = currentState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   409→    this.addGrowthRate('aiCapability', month, currCap, currCap - prevCap);
   410→    
   411→    // Alignment drift
   412→    const prevAlign = prevState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / prevState.aiAgents.length;
   413→    const currAlign = currentState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / currentState.aiAgents.length;
   414→    this.addGrowthRate('alignment', month, currAlign, currAlign - prevAlign);
   415→    
   416→    // Unemployment growth
   417→    this.addGrowthRate('unemployment', month, currentState.society.unemploymentLevel,
   418→      currentState.society.unemploymentLevel - prevState.society.unemploymentLevel);
   419→    
   420→    // Trust decay
   421→    this.addGrowthRate('trustInAI', month, currentState.society.trustInAI,
   422→      currentState.society.trustInAI - prevState.society.trustInAI);
   423→  }
   424→  
   425→  /**
   426→   * Add a growth rate measurement
   427→   */
   428→  private addGrowthRate(metric: string, month: number, value: number, rate: number): void {
   429→    if (!this.growthRates.has(metric)) {
   430→      this.growthRates.set(metric, []);
   431→    }
   432→    
   433→    const rates = this.growthRates.get(metric)!;
   434→    
   435→    // Calculate 3-month moving average
   436→    const recentRates = rates.slice(-2).map(r => r.rate);
   437→    recentRates.push(rate);
   438→    const movingAverage = recentRates.reduce((sum, r) => sum + r, 0) / recentRates.length;
   439→    
   440→    rates.push({
   441→      month,
   442→      metric,
   443→      value,
   444→      rate,
   445→      movingAverage
   446→    });
   447→  }
   448→  
   449→  /**
   450→   * Log an intervention and its impact
   451→   */
   452→  private logIntervention(state: GameState, event: GameEvent): void {
   453→    const month = state.currentMonth;
   454→    const totalCap = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   455→    const avgAlign = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / state.aiAgents.length;
   456→    
   457→    this.interventions.push({
   458→      month,
   459→      action: event.title,
   460→      agent: event.agent,
   461→      before: this.previousState ? {
   462→        aiCapability: this.previousState.aiAgents.reduce((sum, ai) => sum + ai.capability, 0),
   463→        alignment: this.previousState.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / this.previousState.aiAgents.length,
   464→        unemployment: this.previousState.society.unemploymentLevel,
   465→        trust: this.previousState.society.trustInAI
   466→      } : {},
   467→      after: {
   468→        aiCapability: totalCap,
   469→        alignment: avgAlign,
   470→        unemployment: state.society.unemploymentLevel,
   471→        trust: state.society.trustInAI
   472→      },
   473→      effects: event.effects
   474→    });
   475→  }
