   477→  /**
   478→   * Finalize and generate diagnostic report
   479→   */
   480→  finalize(finalState: GameState, outcome: string): DiagnosticLog {
   481→    // Find key tipping points (thresholds that preceded rapid changes)
   482→    const keyTippingPoints = this.identifyKeyTippingPoints();
   483→    
   484→    // Find fastest growth period
   485→    const fastestGrowth = this.findFastestGrowthPeriod();
   486→    
   487→    // Evaluate intervention effectiveness
   488→    const { mostEffective, leastEffective } = this.evaluateInterventions();
   489→    
   490→    // Calculate government response delay
   491→    const responseDelay = this.firstAIThreat > 0 && this.firstGovernmentAction > 0
   492→      ? this.firstGovernmentAction - this.firstAIThreat
   493→      : undefined;
   494→    
   495→    // Count interventions by agent
   496→    const interventionCount = {
   497→      ai: this.interventions.filter(i => i.agent && i.agent.includes('AI')).length,
   498→      government: this.interventions.filter(i => i.agent === 'Government').length,
   499→      society: this.interventions.filter(i => i.agent === 'Society').length
   500→    };
   501→    
   502→    // Calculate correlations
   503→    const correlations = this.calculateCorrelations();
   504→    
   505→    // Phase 4: Calculate lifecycle statistics
   506→    const lifecycleStats = this.lifecycleSnapshots.length > 0 ? {
   507→      peakActiveAIs: Math.max(...this.lifecycleSnapshots.map(s => s.totalActive)),
   508→      peakSpreadCount: Math.max(...this.lifecycleSnapshots.map(s => s.totalSpread)),
   509→      totalAIsCreated: this.lifecycleSnapshots.reduce((sum, s) => sum + s.newThisMonth, 0),
   510→      totalAIsRetired: this.lifecycleSnapshots.reduce((sum, s) => sum + s.retiredThisMonth, 0),
   511→      avgLifespan: finalState.aiAgents.length > 0
   512→        ? finalState.aiAgents
   513→            .filter(ai => ai.lifecycleState === 'retired')
   514→            .reduce((sum, ai) => sum + ai.monthsInExistence, 0) / 
   515→          Math.max(1, finalState.aiAgents.filter(ai => ai.lifecycleState === 'retired').length)
   516→        : 0
   517→    } : undefined;
   518→    
   519→    return {
   520→      thresholdCrossings: this.thresholdCrossings,
   521→      growthRates: Array.from(this.growthRates.values()).flat(),
   522→      interventions: this.interventions,
   523→      decisions: this.decisions,
   524→      lifecycleSnapshots: this.lifecycleSnapshots,
   525→
   526→      // P0.4 (Oct 15, 2025): Include system snapshots
   527→      populationSnapshots: this.populationSnapshots,
   528→      resourceSnapshots: this.resourceSnapshots,
   529→      environmentalSnapshots: this.environmentalSnapshots,
   530→      economicSnapshots: this.economicSnapshots,
   531→      cascadeSnapshots: this.cascadeSnapshots,
   532→
   533→      correlations,
   534→      summary: {
   535→        extinctionReason: outcome === 'extinction' ? 'Simulation ended in extinction' : undefined,
   536→        extinctionMonth: outcome === 'extinction' ? finalState.currentMonth : undefined,
   537→        keyTippingPoints,
   538→        fastestGrowthPeriod: fastestGrowth,
   539→        mostEffectiveIntervention: mostEffective,
   540→        leastEffectiveIntervention: leastEffective,
   541→        governmentResponseDelay: responseDelay,
   542→        interventionCount,
   543→        lifecycleStats
   544→      }
   545→    };
   546→  }
   547→  
   548→  /**
   549→   * Identify the most significant tipping points
   550→   */
   551→  private identifyKeyTippingPoints(): ThresholdCrossing[] {
   552→    // Find crossings followed by rapid acceleration
   553→    return this.thresholdCrossings
   554→      .filter(crossing => {
   555→        // Look for crossings of high-value thresholds
   556→        if (crossing.metric === 'aiCapability' && crossing.threshold >= 1.0) return true;
   557→        if (crossing.metric === 'alignment' && crossing.threshold <= 0.6) return true;
   558→        if (crossing.metric === 'unemployment' && crossing.threshold >= 0.25) return true;
   559→        if (crossing.metric === 'trustInAI' && crossing.threshold <= 0.4) return true;
   560→        return false;
   561→      })
   562→      .slice(0, 5); // Top 5 most critical
   563→  }
   564→  
   565→  /**
   566→   * Find the period with fastest metric growth
   567→   */
   568→  private findFastestGrowthPeriod(): { startMonth: number; endMonth: number; metric: string; rate: number } {
   569→    let fastest = { startMonth: 0, endMonth: 0, metric: '', rate: 0 };
   570→    
   571→    for (const [metric, rates] of this.growthRates.entries()) {
   572→      for (let i = 0; i < rates.length - 2; i++) {
   573→        const window = rates.slice(i, i + 3);
   574→        const avgRate = window.reduce((sum, r) => sum + Math.abs(r.rate), 0) / window.length;
   575→        
   576→        if (avgRate > fastest.rate) {
   577→          fastest = {
   578→            startMonth: window[0].month,
   579→            endMonth: window[window.length - 1].month,
   580→            metric,
   581→            rate: avgRate
   582→          };
   583→        }
   584→      }
   585→    }
   586→    
   587→    return fastest;
   588→  }
   589→  
   590→  /**
   591→   * Evaluate which interventions were most/least effective
   592→   */
   593→  private evaluateInterventions(): { 
   594→    mostEffective?: InterventionImpact;
   595→    leastEffective?: InterventionImpact;
   596→  } {
   597→    if (this.interventions.length === 0) {
   598→      return {};
   599→    }
   600→    
   601→    // Score interventions by their impact on key metrics
   602→    const scored = this.interventions.map(intervention => {
   603→      let score = 0;
   604→      
   605→      // Positive: Slowed AI capability growth
   606→      if (intervention.after.aiCapability < intervention.before.aiCapability) {
   607→        score += 10;
   608→      }
   609→      
   610→      // Positive: Improved alignment
   611→      if (intervention.after.alignment > intervention.before.alignment) {
   612→        score += 8;
   613→      }
   614→      
   615→      // Positive: Reduced unemployment
   616→      if (intervention.after.unemployment < intervention.before.unemployment) {
   617→        score += 5;
   618→      }
   619→      
   620→      // Positive: Increased trust
   621→      if (intervention.after.trust > intervention.before.trust) {
   622→        score += 3;
   623→      }
   624→      
   625→      return { intervention, score };
   626→    });
   627→    
   628→    scored.sort((a, b) => b.score - a.score);
   629→    
   630→    return {
   631→      mostEffective: scored[0]?.intervention,
   632→      leastEffective: scored[scored.length - 1]?.intervention
   633→    };
   634→  }
