   651→/**
   652→ * Format diagnostic log for human reading
   653→ */
   654→export function formatDiagnosticReport(log: DiagnosticLog): string {
   655→  const lines: string[] = [];
   656→  
   657→  lines.push('═══════════════════════════════════════════════════════');
   658→  lines.push('           COMPREHENSIVE DIAGNOSTIC REPORT');
   659→  lines.push('═══════════════════════════════════════════════════════\n');
   660→  
   661→  // Summary
   662→  if (log.summary.extinctionReason) {
   663→    lines.push(`🔴 OUTCOME: Extinction at month ${log.summary.extinctionMonth}\n`);
   664→  }
   665→  
   666→  // Response timing
   667→  if (log.summary.governmentResponseDelay !== undefined) {
   668→    lines.push(`⏱️  RESPONSE DELAY: ${log.summary.governmentResponseDelay} months`);
   669→    lines.push(`   (Time between AI threat emerging and first government action)\n`);
   670→  }
   671→  
   672→  // Intervention counts
   673→  lines.push(`📊 INTERVENTION COUNTS:`);
   674→  lines.push(`   AI Actions:         ${log.summary.interventionCount.ai}`);
   675→  lines.push(`   Government Actions: ${log.summary.interventionCount.government}`);
   676→  lines.push(`   Society Actions:    ${log.summary.interventionCount.society}\n`);
   677→  
   678→  // Key tipping points
   679→  if (log.summary.keyTippingPoints.length > 0) {
   680→    lines.push(`🎯 KEY TIPPING POINTS:`);
   681→    log.summary.keyTippingPoints.forEach(tp => {
   682→      const dir = tp.direction === 'up' ? '↑' : '↓';
   683→      lines.push(`   Month ${tp.month}: ${tp.metric} ${dir} ${tp.threshold.toFixed(2)} (now ${tp.value.toFixed(2)})`);
   684→    });
   685→    lines.push('');
   686→  }
   687→  
   688→  // Fastest growth period
   689→  if (log.summary.fastestGrowthPeriod.rate > 0) {
   690→    const fg = log.summary.fastestGrowthPeriod;
   691→    lines.push(`⚡ FASTEST GROWTH PERIOD:`);
   692→    lines.push(`   Months ${fg.startMonth}-${fg.endMonth}: ${fg.metric}`);
   693→    lines.push(`   Average rate: ${fg.rate.toFixed(4)}/month\n`);
   694→  }
   695→  
   696→  // Most effective intervention
   697→  if (log.summary.mostEffectiveIntervention) {
   698→    const interv = log.summary.mostEffectiveIntervention;
   699→    lines.push(`✅ MOST EFFECTIVE INTERVENTION:`);
   700→    lines.push(`   Month ${interv.month}: ${interv.action}`);
   701→    lines.push(`   Agent: ${interv.agent}`);
   702→    if (interv.before.aiCapability !== undefined) {
   703→      lines.push(`   AI Capability: ${interv.before.aiCapability.toFixed(2)} → ${interv.after.aiCapability.toFixed(2)}`);
   704→    }
   705→    if (interv.before.alignment !== undefined) {
   706→      lines.push(`   Alignment: ${interv.before.alignment.toFixed(2)} → ${interv.after.alignment.toFixed(2)}`);
   707→    }
   708→    lines.push('');
   709→  }
   710→  
   711→  // Growth rates summary
   712→  const capRates = log.growthRates.filter(r => r.metric === 'aiCapability');
   713→  if (capRates.length > 0) {
   714→    const avgGrowth = capRates.reduce((sum, r) => sum + r.rate, 0) / capRates.length;
   715→    const maxGrowth = Math.max(...capRates.map(r => r.rate));
   716→    lines.push(`📈 AI CAPABILITY GROWTH:`);
   717→    lines.push(`   Average: ${avgGrowth.toFixed(4)}/month`);
   718→    lines.push(`   Maximum: ${maxGrowth.toFixed(4)}/month\n`);
   719→  }
   720→  
   721→  const alignRates = log.growthRates.filter(r => r.metric === 'alignment');
   722→  if (alignRates.length > 0) {
   723→    const avgDrift = alignRates.reduce((sum, r) => sum + r.rate, 0) / alignRates.length;
   724→    const maxDrift = Math.min(...alignRates.map(r => r.rate));
   725→    lines.push(`📉 ALIGNMENT DRIFT:`);
   726→    lines.push(`   Average: ${avgDrift.toFixed(4)}/month`);
   727→    lines.push(`   Worst: ${maxDrift.toFixed(4)}/month\n`);
   728→  }
   729→  
   730→  lines.push('═══════════════════════════════════════════════════════\n');
   731→  
   732→  return lines.join('\n');
   733→}
   734→
   735→/**
   736→ * P0.4 (Oct 15, 2025): Compare diagnostics across multiple Monte Carlo runs
   737→ * Identifies systems with suspiciously low variance (deterministic behavior)
   738→ */
   739→export interface DeterminismAnalysis {
   740→  month: number;
   741→  system: string;
   742→  metric: string;
   743→  values: number[];
   744→  mean: number;
   745→  stdDev: number;
   746→  coefficientOfVariation: number; // std/mean - should be >5% for stochastic systems
   747→  isDeterministic: boolean; // CV < 0.01 (1%)
   748→}
   749→
   750→export function analyzeDeterminism(logs: DiagnosticLog[]): {
   751→  summary: string;
   752→  analyses: DeterminismAnalysis[];
   753→  deterministicSystems: string[];
   754→} {
   755→  const analyses: DeterminismAnalysis[] = [];
   756→  const deterministicSystems = new Set<string>();
   757→
   758→  // Helper to calculate stats
   759→  const calculateStats = (values: number[]) => {
   760→    const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
   761→    const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
   762→    const stdDev = Math.sqrt(variance);
   763→    const cv = mean !== 0 ? Math.abs(stdDev / mean) : 0;
   764→    return { mean, stdDev, cv };
   765→  };
   766→
   767→  // Analyze at key time points (month 60, 120, 180, 240)
   768→  const checkMonths = [60, 120, 180, 240];
   769→
   770→  for (const month of checkMonths) {
   771→    // Population metrics
   772→    const popData = logs.map(log =>
   773→      log.populationSnapshots.find(s => s.month === month)
   774→    ).filter(s => s !== undefined);
   775→
   776→    if (popData.length > 0) {
   777→      const metrics: Array<[string, number[]]> = [
   778→        ['Population', popData.map(s => s!.population)],
   779→        ['Birth Rate', popData.map(s => s!.birthRate)],
   780→        ['Death Rate', popData.map(s => s!.deathRate)],
   781→        ['Environmental Mortality', popData.map(s => s!.mortalityByEnvironment)],
   782→        ['Famine Mortality', popData.map(s => s!.mortalityByFamine)]
   783→      ];
   784→
   785→      for (const [metric, values] of metrics) {
   786→        const stats = calculateStats(values);
   787→        const isDeterministic = stats.cv < 0.01; // Less than 1% variation
   788→        analyses.push({
   789→          month,
   790→          system: 'Population',
   791→          metric,
   792→          values,
   793→          mean: stats.mean,
   794→          stdDev: stats.stdDev,
   795→          coefficientOfVariation: stats.cv,
   796→          isDeterministic
   797→        });
   798→        if (isDeterministic) deterministicSystems.add(`Population.${metric}`);
   799→      }
   800→    }
   801→
   802→    // Environmental metrics
   803→    const envData = logs.map(log =>
   804→      log.environmentalSnapshots.find(s => s.month === month)
   805→    ).filter(s => s !== undefined);
   806→
   807→    if (envData.length > 0) {
   808→      const metrics: Array<[string, number[]]> = [
   809→        ['Climate Stability', envData.map(s => s!.climateStability)],
   810→        ['Biodiversity Index', envData.map(s => s!.biodiversityIndex)],
   811→        ['Tipping Point Risk', envData.map(s => s!.tippingPointRisk)]
   812→      ];
   813→
   814→      for (const [metric, values] of metrics) {
   815→        const stats = calculateStats(values);
   816→        const isDeterministic = stats.cv < 0.01;
   817→        analyses.push({
   818→          month,
   819→          system: 'Environmental',
   820→          metric,
   821→          values,
   822→          mean: stats.mean,
   823→          stdDev: stats.stdDev,
   824→          coefficientOfVariation: stats.cv,
   825→          isDeterministic
   826→        });
   827→        if (isDeterministic) deterministicSystems.add(`Environmental.${metric}`);
   828→      }
   829→    }
   830→
   831→    // Resource metrics
   832→    const resData = logs.map(log =>
   833→      log.resourceSnapshots.find(s => s.month === month)
   834→    ).filter(s => s !== undefined);
   835→
   836→    if (resData.length > 0) {
   837→      const metrics: Array<[string, number[]]> = [
   838→        ['Food Security', resData.map(s => s!.foodSecurity)],
   839→        ['Food Stock', resData.map(s => s!.foodStock)],
   840→        ['Water Stock', resData.map(s => s!.waterStock)]
   841→      ];
   842→
   843→      for (const [metric, values] of metrics) {
   844→        const stats = calculateStats(values);
   845→        const isDeterministic = stats.cv < 0.01;
   846→        analyses.push({
   847→          month,
   848→          system: 'Resource',
   849→          metric,
   850→          values,
   851→          mean: stats.mean,
   852→          stdDev: stats.stdDev,
   853→          coefficientOfVariation: stats.cv,
   854→          isDeterministic
   855→        });
   856→        if (isDeterministic) deterministicSystems.add(`Resource.${metric}`);
   857→      }
   858→    }
   859→
   860→    // Cascade metrics
   861→    const cascadeData = logs.map(log =>
   862→      log.cascadeSnapshots.find(s => s.month === month)
   863→    ).filter(s => s !== undefined);
   864→
   865→    if (cascadeData.length > 0) {
   866→      const metrics: Array<[string, number[]]> = [
   867→        ['Cascade Severity', cascadeData.map(s => s!.cascadeSeverity)],
   868→        ['Active Crises', cascadeData.map(s => s!.activeCrises)],
   869→        ['Cumulative Deaths', cascadeData.map(s => s!.cumulativeDeaths)]
   870→      ];
   871→
   872→      for (const [metric, values] of metrics) {
   873→        const stats = calculateStats(values);
   874→        const isDeterministic = stats.cv < 0.01;
   875→        analyses.push({
   876→          month,
   877→          system: 'Cascade',
   878→          metric,
   879→          values,
   880→          mean: stats.mean,
   881→          stdDev: stats.stdDev,
   882→          coefficientOfVariation: stats.cv,
   883→          isDeterministic
   884→        });
   885→        if (isDeterministic) deterministicSystems.add(`Cascade.${metric}`);
   886→      }
   887→    }
   888→  }
   889→
   890→  // Generate summary
   891→  const deterministicCount = deterministicSystems.size;
   892→  const totalMetrics = analyses.length;
   893→  const deterministicPct = (deterministicCount / totalMetrics * 100).toFixed(1);
   894→
   895→  const summary = `
   896→═══════════════════════════════════════════════════════
   897→   DETERMINISM ANALYSIS - ${logs.length} Monte Carlo Runs
   898→═══════════════════════════════════════════════════════
   899→
   900→🔴 DETERMINISTIC SYSTEMS: ${deterministicCount}/${totalMetrics} metrics (${deterministicPct}%)
   901→
   902→${Array.from(deterministicSystems).map(sys => `   - ${sys}`).join('\n')}
   903→
   904→Metrics with CV < 1% are considered deterministic.
   905→Healthy stochastic systems should have CV > 5%.
   906→
   907→Analyzed at months: ${checkMonths.join(', ')}
   908→`;
   909→
   910→  return {
   911→    summary,
   912→    analyses,
   913→    deterministicSystems: Array.from(deterministicSystems)
   914→  };
   915→}
   916→
   917→/**
   918→ * P0.4: Format determinism analysis for readable output
   919→ */
   920→export function formatDeterminismReport(analysis: ReturnType<typeof analyzeDeterminism>): string {
   921→  const lines: string[] = [];
   922→
   923→  lines.push(analysis.summary);
   924→
   925→  // Group by system and month
   926→  const bySystem = new Map<string, DeterminismAnalysis[]>();
   927→  for (const a of analysis.analyses) {
   928→    const key = a.system;
   929→    if (!bySystem.has(key)) bySystem.set(key, []);
   930→    bySystem.get(key)!.push(a);
   931→  }
   932→
   933→  for (const [system, analyses] of bySystem) {
   934→    const deterministic = analyses.filter(a => a.isDeterministic);
   935→    if (deterministic.length > 0) {
   936→      lines.push(`\n🔴 ${system} System (${deterministic.length} deterministic metrics):`);
   937→      for (const a of deterministic) {
   938→        lines.push(`   Month ${a.month}: ${a.metric}`);
   939→        lines.push(`      Mean: ${a.mean.toFixed(4)}, StdDev: ${a.stdDev.toFixed(6)}, CV: ${(a.coefficientOfVariation * 100).toFixed(2)}%`);
   940→        lines.push(`      Values: ${a.values.slice(0, 5).map(v => v.toFixed(4)).join(', ')}${a.values.length > 5 ? '...' : ''}`);
   941→      }
   942→    }
   943→  }
   944→
   945→  lines.push('\n═══════════════════════════════════════════════════════\n');
   946→
   947→  return lines.join('\n');
   948→}
