// 3. Apply famine deaths via Bayesian mortality system (Oct 27, 2025)
if (famineDeaths > 0) {
  // Calculate base risk (as fraction of population)
  const baseRisk = famineDeaths / state.humanPopulationSystem.population;

  // Attribute deaths based on active famine causes
  const famines = state.famineSystem.activeFamines;
  if (famines.length > 0) {
    // Count famines by root cause
    let conflictFamines = 0;
    let climateFamines = 0;
    let governanceFamines = 0;
    let naturalFamines = 0;

    for (const famine of famines) {
      if (famine.cause === 'war_displacement' || famine.cause === 'aid_blockade' || famine.cause === 'nuclear_winter') {
        conflictFamines++;
      } else if (famine.cause === 'crop_failure') {
        climateFamines++;
      } else if (famine.cause === 'drought') {
        naturalFamines++; // Natural drought (may be climate-driven)
      } else {
        governanceFamines++; // economic_collapse, resource_extraction
      }
    }

    const total = conflictFamines + climateFamines + governanceFamines + naturalFamines;
    if (total > 0) {
      // Add separate mortality risks for each root cause (Bayesian compounding)
      if (conflictFamines > 0) {
        addMortalityRisk(state.humanPopulationSystem, {
          type: 'famine',
          baseRisk: baseRisk * (conflictFamines / total),
          proximate: 'famine',
          root: 'conflict',
          confidence: 'HIGH',
          month: state.currentMonth,
          description: 'Famine from war displacement/aid blockade',
        });
      }
      if (climateFamines > 0) {
        addMortalityRisk(state.humanPopulationSystem, {
