  const deathsInBillions = event.deaths / 1000;

  // Apply via Bayesian mortality system (Oct 27, 2025)
  const population = state.humanPopulationSystem;

  if (deathsInBillions > 0) {
    const baseRisk = deathsInBillions / population.population;

    // Calculate exposed fraction (regional wet bulb events)
